    }

    /* ==========================================================================
       PREMIUM UI — tampilan real / glossy (override; ID, class pemicu & logika tetap)
       ========================================================================== */
    @keyframes pgRise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
    @keyframes pgFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
    @keyframes pgPulse { 0% { box-shadow: 0 0 0 0 rgba(255,255,255,.7); } 70% { box-shadow: 0 0 0 7px rgba(255,255,255,0); } 100% { box-shadow: 0 0 0 0 rgba(255,255,255,0); } }

    .content-wrapper.bg-light {
        background:
            radial-gradient(1000px 440px at 10% -8%, rgba(56,189,248,.18), transparent 62%),
            radial-gradient(900px 420px at 100% 0%, rgba(16,185,129,.13), transparent 58%),
            radial-gradient(700px 480px at 50% 110%, rgba(99,102,241,.10), transparent 60%),
            #eef3f9 !important;
    }

    /* ikon */
    .pg-ic { width: 16px; height: 16px; display: inline-block; vertical-align: -3px; flex: none; filter: drop-shadow(0 1px 1.5px rgba(0,0,0,.28)); }
    .pg-ic.pg-lg {
        width: 40px; height: 40px; padding: 6px; border-radius: 13px; vertical-align: middle; margin-right: 12px !important;
        background: linear-gradient(150deg, #ffffff, #eef2ff); border: 1px solid #e0e7ff;
        box-shadow: inset 0 1px 0 #fff, 0 8px 14px -8px rgba(37,99,235,.55); filter: drop-shadow(0 2px 2px rgba(0,0,0,.18));
    }
    .btn .pg-ic { width: 18px; height: 18px; vertical-align: -4px; }
    .btn-action-sm .pg-ic { width: 18px; height: 18px; vertical-align: -4px; transition: transform .2s; }
    .btn-action-sm:hover .pg-ic { transform: scale(1.15) rotate(-4deg); }
    .media .pg-ic { width: 15px; height: 15px; vertical-align: -3px; }
    .pg-empty-ic { width: 44px !important; height: 44px !important; margin-bottom: 6px; opacity: .9; }

    /* hero */
    .pg-hero {
        position: relative; overflow: hidden; isolation: isolate; border-radius: 26px; padding: 26px 30px; margin-bottom: 26px; color: #fff;
        display: grid; grid-template-columns: auto 1fr auto; gap: 8px 22px; align-items: center;
        background: radial-gradient(60% 130% at 94% -25%, rgba(56,189,248,.5), transparent 62%), radial-gradient(50% 100% at 0% 125%, rgba(16,185,129,.4), transparent 60%), linear-gradient(150deg, #0a1b4d 0%, #16318f 55%, #2563eb 100%);
        border: 1px solid rgba(255,255,255,.18);
        box-shadow: 0 34px 64px -30px rgba(15,40,120,.75), inset 0 1.5px 0 rgba(255,255,255,.25);
        animation: pgRise .6s cubic-bezier(.2,.7,.2,1) both;
    }
    .pg-hero::before {
        content: ''; position: absolute; inset: 0; z-index: -1; opacity: .5; pointer-events: none;
        background-image: linear-gradient(rgba(255,255,255,.07) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.07) 1px, transparent 1px);
        background-size: 28px 28px; -webkit-mask: radial-gradient(ellipse at 75% 0%, #000, transparent 70%); mask: radial-gradient(ellipse at 75% 0%, #000, transparent 70%);
    }
    .pg-orb {
        width: 92px; height: 92px; border-radius: 50%; display: grid; place-items: center; animation: pgFloat 4.2s ease-in-out infinite;
        background: radial-gradient(circle at 30% 24%, rgba(255,255,255,.55), rgba(255,255,255,.12) 64%); border: 1px solid rgba(255,255,255,.5);
        box-shadow: inset 0 2px 0 rgba(255,255,255,.6), inset 0 -10px 16px rgba(20,40,150,.4), 0 16px 30px rgba(5,15,60,.55), 0 0 0 9px rgba(255,255,255,.06);
    }
    .pg-orb svg { width: 56px; height: 56px; filter: drop-shadow(0 6px 7px rgba(0,0,0,.4)); }
    .pg-eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: .7rem; font-weight: 800; letter-spacing: .22em; color: #bbf7d0; margin-bottom: 6px; }
    .pg-dot { width: 8px; height: 8px; border-radius: 50%; background: #86efac; display: inline-block; animation: pgPulse 1.8s infinite; }
    .pg-hero h2 { margin: 0 0 4px; font-size: clamp(1.5rem, 3.4vw, 2rem); font-weight: 800; letter-spacing: -.5px; color: #fff; text-shadow: 0 3px 10px rgba(0,0,0,.3); }
    .pg-hero p { margin: 0; color: #cfe0ff; font-size: .92rem; }
    .pg-chips { display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }
    .pg-chip {
        display: inline-flex; align-items: center; gap: 8px; padding: 7px 16px 7px 10px; border-radius: 999px; font-size: .82rem; font-weight: 700;
        background: linear-gradient(150deg, rgba(255,255,255,.22), rgba(255,255,255,.06)); border: 1px solid rgba(255,255,255,.28); box-shadow: inset 0 1px 0 rgba(255,255,255,.35);
    }
    .pg-chip b { font-size: 1rem; }
    .pg-chip .pg-ic { width: 20px; height: 20px; }

    /* kartu */
    .modern-card {
        position: relative; border: 1px solid rgba(203,213,225,.55) !important; border-radius: 22px !important;
        background: linear-gradient(180deg, #ffffff, #fbfcfe);
        box-shadow: 0 26px 44px -26px rgba(15,23,42,.45), 0 4px 10px -4px rgba(15,23,42,.07), inset 0 1.5px 0 #fff !important;
